<template><div class="task-page"><el-card><template #header><div class="task-card-header"><span>学习记录</span><el-button type="primary" @click="visible=true">新增记录</el-button></div></template><el-form inline><el-form-item label="学习计划"><el-select v-model="planId" clearable style="width:220px" @change="load"><el-option v-for="p in plans" :key="p.id" :label="p.title" :value="p.id"/></el-select></el-form-item><el-form-item label="关键词"><el-input v-model="keyword" clearable @keyup.enter="load"/></el-form-item><el-button @click="load">查询</el-button></el-form><el-timeline class="learning-timeline"><el-timeline-item v-for="r in records" :key="r.id" :timestamp="format(r.recordTime)" placement="top"><el-card><div class="task-card-header"><b>{{planName(r.planId)}}</b><el-tag>{{r.durationMinutes}} 分钟</el-tag></div><p>{{r.content}}</p><div v-if="r.result" class="record-detail">成果：{{r.result}}</div><div v-if="r.problem" class="record-detail">问题：{{r.problem}}</div><div v-if="r.nextAction" class="record-detail">下一步：{{r.nextAction}}</div></el-card></el-timeline-item></el-timeline><el-empty v-if="!records.length" description="暂无学习记录"/></el-card>
<el-dialog v-model="visible" title="新增学习记录" width="620px"><el-form :model="form" label-width="90px"><el-form-item label="学习计划" required><el-select v-model="form.planId" style="width:100%"><el-option v-for="p in plans" :key="p.id" :label="p.title" :value="p.id"/></el-select></el-form-item><el-form-item label="学习内容" required><el-input v-model="form.content" type="textarea" :rows="3"/></el-form-item><el-form-item label="学习耗时"><el-input-number v-model="form.durationMinutes" :min="0"/><span class="form-help">分钟</span></el-form-item><el-form-item label="记录时间"><el-date-picker v-model="form.recordTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="学习成果"><el-input v-model="form.result" type="textarea"/></el-form-item><el-form-item label="遇到问题"><el-input v-model="form.problem" type="textarea"/></el-form-item><el-form-item label="下一步"><el-input v-model="form.nextAction" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{onMounted,reactive,ref}from'vue';import{createLearningRecord,listLearningRecords,listPlans,type LearningPlan,type LearningRecord}from'@/api/learning';const plans=ref<LearningPlan[]>([]),records=ref<LearningRecord[]>([]),planId=ref<number>(),keyword=ref(''),visible=ref(false);const localNow=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,19)};const form=reactive({planId:undefined as number|undefined,content:'',durationMinutes:30,result:'',problem:'',nextAction:'',recordTime:localNow()});function planName(id:number){return plans.value.find(p=>p.id===id)?.title||`计划 #${id}`;}function format(v:string){return new Date(v).toLocaleString('zh-CN');}async function load(){records.value=(await listLearningRecords({planId:planId.value,keyword:keyword.value||undefined})).data;}async function save(){if(!form.planId||!form.content.trim()){ElMessage.warning('请选择计划并填写学习内容');return;}await createLearningRecord(form);ElMessage.success('记录已保存');visible.value=false;form.content='';await load();}onMounted(async()=>{plans.value=(await listPlans()).data;await load();});</script>